CREATE OR REPLACE FUNCTION public.bill2_payg_admin_settle_call(p_admin_id uuid, p_request_id uuid, p_call_id uuid, p_verified_cost_usd numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
