 THEN RAISE EXCEPTION 'BILL2_ADMIN_SETTLE_DENIED' USING ERRCODE='42501';END IF;
 IF p_request_id IS NULL OR p_call_id IS NULL OR p_verified_cost_usd IS NULL OR p_verified_cost_usd<0
